// Adapter for target "old": binds Surface against the running application, walked with the browser — no selector here is copied from source, because there is no source in this workspace.
import type { Surface } from "../../generated/surface";
import type { Page } from "@playwright/test";
import { persona } from "../../generated/personas";

export default function create(page: Page, ctx: { baseURL: string; persona: typeof persona }): Surface {
  return {
    async signIn(p) {
      const route = p.signIn?.["sandbox-idp"];
      if (!route) throw new Error("unbound: signIn — persona has no sandbox-idp sign_in");
      await page.goto(`${ctx.baseURL}/sign-in`);
      await page.getByLabel("Username").fill(route.username);
      await page.getByLabel("Password").fill(process.env.SDLC_SANDBOX_PASSWORD ?? "");
      await page.getByRole("button", { name: "Sign in" }).click();
    },
    async signOut() {
      await page.getByRole("button", { name: "Sign out" }).click();
    },
    applicationsNew: {
      async open() {
        await page.goto(`${ctx.baseURL}/applications`);
      },
      async submit(input) {
        await page.getByLabel("Age").fill(String((input as { age?: number })?.age ?? ""));
        await page.getByRole("button", { name: "Submit application" }).click();
      },
      async submitProposal(input) {
        await page.getByLabel("Proposal").fill(String((input as { proposal?: string })?.proposal ?? ""));
        await page.getByRole("button", { name: "Submit proposal" }).click();
      },
      async status() {
        return (await page.getByRole("status").textContent()) ?? "";
      },
    },
    feesQuote: {
      async open() {
        await page.goto(`${ctx.baseURL}/fees/quote`);
      },
      async calculate() {
        await page.getByRole("button", { name: "Calculate fee" }).click();
      },
      async amount() {
        return (await page.getByLabel("Fee amount").textContent()) ?? "";
      },
    },
  };
}

